--
-- Name: fn_atualizar_user_ativo(); Type: FUNCTION; Schema: _adm; Owner: postgres
--

CREATE FUNCTION _adm.fn_atualizar_user_ativo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Atualizar ativo em Usuarios
  -- Atualizar o valor de system_users->active quando COLOCABORADOR.ativo for atualizado
  UPDATE _adm.system_users 
  SET active = NEW.ativo
  WHERE idcolaborador = NEW.id;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION _adm.fn_atualizar_user_ativo() OWNER TO postgres;

--
-- Name: fn_atualizar_user_grupo(); Type: FUNCTION; Schema: _adm; Owner: postgres
--

CREATE FUNCTION _adm.fn_atualizar_user_grupo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Atualizar PERFIL em USER
  -- Atualizar o valor de USER.ID_GRUPO quando COLOCABORADOR.ID_GRUPO for atualizado
  UPDATE _adm.system_users 
  SET system_group_id = NEW.system_group_id
  WHERE idcolaborador = NEW.id;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION _adm.fn_atualizar_user_grupo() OWNER TO postgres;

--
-- Name: fn_cepformat(character varying); Type: FUNCTION; Schema: _adm; Owner: postgres
--

CREATE FUNCTION _adm.fn_cepformat(par_cep character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
IF char_length(par_cep) = 8 THEN
	RETURN substring(par_cep FROM 1 FOR 2) || '.' || substring(par_cpf FROM 3 FOR 3) || '-' || substring(par_cpf FROM 6 FOR 3);
END IF;
END;
$$;


ALTER FUNCTION _adm.fn_cepformat(par_cep character varying) OWNER TO postgres;

--
-- Name: fn_cpfcnpjformat(character varying); Type: FUNCTION; Schema: _adm; Owner: postgres
--

CREATE FUNCTION _adm.fn_cpfcnpjformat(par_cpf character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
IF char_length(par_cpf) = 11 THEN
	RETURN substring(par_cpf FROM 1 FOR 3) || '.' || substring(par_cpf FROM 4 FOR 3) || '.' || substring(par_cpf FROM 7 FOR 3) || '-' || substring(par_cpf FROM 10 FOR 2);
else
	IF char_length(par_cpf) = 14 THEN
		RETURN substring(par_cpf FROM 1 FOR 2) || '.' ||
				substring(par_cpf FROM 3 FOR 3) || '.' ||
				substring(par_cpf FROM 6 FOR 3) || '/' ||
				substring(par_cpf FROM 9 FOR 4) || '-' ||
				substring(par_cpf FROM 13 FOR 2);
	else
		RETURN ' ';
	END IF;
END IF;
END;
$$;


ALTER FUNCTION _adm.fn_cpfcnpjformat(par_cpf character varying) OWNER TO postgres;

--
-- Name: fn_percentual(integer, integer); Type: FUNCTION; Schema: _adm; Owner: postgres
--

CREATE FUNCTION _adm.fn_percentual(p_valor_menor integer, p_valor_maior integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$DECLARE
	v_temp float := 0.00;
	v_tmp integer := 0;
	v_chartmp varchar := '';
BEGIN
	IF p_valor_maior = 0 
	THEN
		SELECT 'Erro' INTO v_chartmp;
	ELSE
		SELECT p_valor_menor / p_valor_maior::FLOAT INTO v_temp;	
		SELECT cast( v_temp::float*100 as numeric(9,2) ) INTO v_chartmp;
		--SELECT v_tmp::varchar || ' %' INTO v_chartmp;
	END IF;
	RETURN v_chartmp;
END;
$$;


ALTER FUNCTION _adm.fn_percentual(p_valor_menor integer, p_valor_maior integer) OWNER TO postgres;

