--
-- Name: fn_setrodadacriterios(integer, integer); Type: FUNCTION; Schema: _rodadaconfig; Owner: postgres
--

CREATE FUNCTION _rodadaconfig.fn_setrodadacriterios(idrodada integer, idmetodologia integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO '_rodadaconfig', 'pg_temp'
    AS $_$
DECLARE vMetodoNaRodada INTEGER;
BEGIN
    SELECT dbrm.id 
        INTO    vMetodoNaRodada
        FROM    _rodadaconfig.dbrodadametodologias dbrm
        WHERE   dbrm.idrodada = $1
        AND     dbrm.idmetodologia = $2;

    IF NOT FOUND
    THEN
        RAISE NOTICE 'NÃO ACHOU RODADAMETODOLOGIA';
    ELSE
        DELETE FROM _rodadaconfig.dbrodadacriterios dbrc WHERE (dbrc.idrodada = $1) AND (dbrc.idmetodologia = $2);

            SELECT  $1       AS idrodada,
                    $2       AS idmetodologia, 
                    dbref.id AS idreferencia 
            FROM _referencia.dbreferencia dbref 
            WHERE dbref.idmetodologia = $2 
            ORDER BY dbref.sigla;    
    END IF;
END;
$_$;


ALTER FUNCTION _rodadaconfig.fn_setrodadacriterios(idrodada integer, idmetodologia integer) OWNER TO postgres;

--
-- Name: insererodadacriterios(); Type: FUNCTION; Schema: _rodadaconfig; Owner: postgres
--

CREATE FUNCTION _rodadaconfig.insererodadacriterios() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE vidRodada INTEGER;
DECLARE vidMetodologia INTEGER;
BEGIN
    vidRodada = NEW.idrodada;
    vidMetodologia = NEW.idmetodologia;
    -- trigger logic
        SELECT  vidRodada       AS idrodada,
                vidMetodologia  AS idmetodologia, 
                dbref.id        AS idreferencia 
        FROM _referencia.dbreferencia dbref 
        WHERE dbref.idmetodologia = vidMetodologia 
        ORDER BY dbref.sigla;    
    -- Retorna a Nova Linha da tabela do Trigger
    RETURN NEW;
END;
$$;


ALTER FUNCTION _rodadaconfig.insererodadacriterios() OWNER TO postgres;

