--
-- Name: vwcolaboradordadoscontato; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwcolaboradordadoscontato AS
 SELECT t1.id,
    t3.nome,
    t3.nomefantasia AS nomereduzido,
    t1.login,
    _adm.fn_cpfcnpjformat(t1.login) AS loginformat,
    t1.password,
    t1.frontpage_id,
    t5.name AS nomefuncionalidade,
    t5.controller,
    t1.system_group_id,
    t6.name AS nomegrupo,
    t1.acessasistema,
    t1.accepted_term_policy,
    t1.accepted_term_policy_at,
    t1.active,
    t1.inc_data,
    t1.inc_idusuario,
    t1.alt_data,
    t1.alt_idusuario,
    t1.exc_data,
    t1.accepted_term_policy_data,
    t2.tipocolaborador,
        CASE
            WHEN (t2.tipocolaborador = 1) THEN 'Empregado'::text
            WHEN (t2.tipocolaborador = 2) THEN 'Terceirizado'::text
            ELSE 'Outros'::text
        END AS dsctipocolaborador,
    t2.numcelular,
        CASE
            WHEN (length(t2.numcelular) = 11) THEN regexp_replace(lpad((t2.numcelular)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numcelular) = 10) THEN regexp_replace(lpad((t2.numcelular)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numcelularformat,
    t2.numtelcom,
        CASE
            WHEN (length(t2.numtelcom) = 11) THEN regexp_replace(lpad((t2.numtelcom)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numtelcom) = 10) THEN regexp_replace(lpad((t2.numtelcom)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numtelcomformat,
    t2.numramal,
    t2.iddepartamento,
    t4.nome AS nomedepto,
    t2.pthfotocolaborador AS pthimgusuario,
    t2.pthassinaturaemail,
    t2.emailpessoal AS email,
    t2.cargo,
    t7.tipoendereco,
    t10.valordominio AS dsctipoendereco,
    t7.dsclogradouro,
    t7.numlogradouro,
    (((t7.dsclogradouro)::text || ', '::text) || (t7.numlogradouro)::text) AS logradouro_num,
    t7.dsccomplemento,
    t7.dscbairro,
    t7.numcep,
    regexp_replace((t7.numcep)::text, '(\d{5})(\d{3})'::text, '\1-\2'::text) AS numcepformat,
    (((t8.nmecidade)::text || ' - '::text) || (t9.sgluf)::text) AS nomecidade,
    t2.observacao,
    t11.nomecurso,
    t12.descricao AS nivelescolaridade,
        CASE
            WHEN (t11.nomecurso IS NULL) THEN (t12.descricao)::text
            ELSE (t11.nomecurso)::text
        END AS formacao
   FROM (((((((((((_adm.system_users t1
     JOIN _adm.dbcolaborador t2 ON (((t2.id = t1.idcolaborador) AND (t2.exc_data IS NULL))))
     LEFT JOIN _adm.dbpessoaendereco t7 ON (((t7.idpessoa = t2.idpessoa) AND (t7.grupoorigem = t2.tipocolaborador) AND (t7.staprincipal = 'S'::bpchar) AND (t7.origempessoa = 'C'::bpchar))))
     LEFT JOIN _global.dbcidade t8 ON ((t8.id = t7.idcidade)))
     LEFT JOIN _global.dbestado t9 ON ((t9.id = t8.idestado)))
     LEFT JOIN _global.dbcampodominio t10 ON ((((t10.grupodominio)::text = 'te'::text) AND (t10.indicedominio = t7.tipoendereco))))
     LEFT JOIN _adm.dbpessoa t3 ON ((t3.id = t2.idpessoa)))
     LEFT JOIN _adm.dbdepartamento t4 ON ((t4.id = t2.iddepartamento)))
     LEFT JOIN _global.system_program t5 ON ((t5.id = t1.frontpage_id)))
     LEFT JOIN _adm.system_group t6 ON ((t6.id = t1.system_group_id)))
     LEFT JOIN _global.dbcursoformacaosuperior t11 ON ((t11.id = t2.idcursoformsup)))
     LEFT JOIN _global.dbnivelescolaridade t12 ON ((t12.id = t2.idnivelescolaridade)));


ALTER VIEW _adm.vwcolaboradordadoscontato OWNER TO postgres;

--
-- Name: vwcolaboradorusuario; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwcolaboradorusuario AS
 SELECT t1.id,
    t3.nome,
    t3.nomefantasia AS nomereduzido,
    t3.cpfcnpj,
    _adm.fn_cpfcnpjformat(t3.cpfcnpj) AS cpfcnpjformat,
    t1.login,
    t1.password,
    t1.frontpage_id,
    t5.name AS nomefuncionalidade,
    t5.controller,
    t1.system_group_id,
    t6.name AS nomegrupo,
    t1.acessasistema,
    t1.accepted_term_policy,
    t1.accepted_term_policy_at,
    t1.active,
    t1.inc_data,
    t1.inc_idusuario,
    t1.alt_data,
    t1.alt_idusuario,
    t1.exc_data,
    t1.accepted_term_policy_data,
    t1.tipoidioma,
    t2.tipocolaborador,
        CASE
            WHEN (t2.tipocolaborador = 1) THEN 'Empregado'::text
            WHEN (t2.tipocolaborador = 2) THEN 'Terceirizado'::text
            ELSE 'Outros'::text
        END AS dsctipocolaborador,
    t2.numcelular,
        CASE
            WHEN (length(t2.numcelular) = 11) THEN regexp_replace(lpad((t2.numcelular)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numcelular) = 10) THEN regexp_replace(lpad((t2.numcelular)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numcelularformat,
    t2.numtelcom,
        CASE
            WHEN (length(t2.numtelcom) = 11) THEN regexp_replace(lpad((t2.numtelcom)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numtelcom) = 10) THEN regexp_replace(lpad((t2.numtelcom)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numtelcomformat,
    t2.numramal,
    t2.iddepartamento,
    t2.cargo,
    t4.nome AS nomedepto,
    t2.pthfotocolaborador AS pthimgusuario,
    t2.pthassinaturaemail,
    t2.emailpessoal AS email,
    t2.observacao,
    t1.custom_code,
    t1.otp_secret
   FROM (((((_adm.system_users t1
     JOIN _adm.dbcolaborador t2 ON (((t2.id = t1.idcolaborador) AND (t2.exc_data IS NULL))))
     LEFT JOIN _adm.dbpessoa t3 ON ((t3.id = t2.idpessoa)))
     LEFT JOIN _adm.dbdepartamento t4 ON ((t4.id = t2.iddepartamento)))
     LEFT JOIN _global.system_program t5 ON ((t5.id = t1.frontpage_id)))
     LEFT JOIN _adm.system_group t6 ON ((t6.id = t1.system_group_id)));


ALTER VIEW _adm.vwcolaboradorusuario OWNER TO postgres;

--
-- Name: vwfuncionalidadeconfigs; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwfuncionalidadeconfigs AS
 SELECT fc.id,
    fc.idusuario,
    vc.nome AS nomeusuario,
    fc.idfuncionalidade,
    sp.name AS nomefuncionalidade,
    sp.controller AS nomeclasse,
    sp.tipofunc,
    cd.valordominio AS dsctipofunc,
    (fc.configs ->> 'qtditemsgrid'::text) AS qtditemsgrid,
    (fc.configs ->> 'alturaform'::text) AS alturaform,
    (fc.configs ->> 'expandeform'::text) AS expandeform,
    (fc.configs ->> 'agrupaportipo'::text) AS agrupaportipo,
    (fc.configs ->> 'agrupaporgrupo'::text) AS agrupaporgrupo,
    (fc.configs ->> 'agrupaportipopb'::text) AS agrupaportipopb,
    (fc.configs ->> 'agrupapormetodologia'::text) AS agrupapormetodologia
   FROM (((_adm.dbfuncionalidadeconfigs fc
     LEFT JOIN _adm.vwcolaboradorusuario vc ON ((vc.id = fc.idusuario)))
     LEFT JOIN _global.system_program sp ON ((sp.id = fc.idfuncionalidade)))
     LEFT JOIN _global.dbcampodominio cd ON ((((cd.grupodominio)::bpchar = 'tfu'::bpchar) AND (cd.indicedominio = sp.tipofunc))));


ALTER VIEW _adm.vwfuncionalidadeconfigs OWNER TO postgres;

