--
-- Name: vwgrupolista; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwgrupolista AS
 SELECT id,
    name,
    active,
    perfiladm,
    ( SELECT count(sgp.system_group_id) AS count
           FROM _adm.system_group_program sgp
          WHERE (sgp.system_group_id = sg.id)) AS qtdfuncs,
    ( SELECT count(su.system_group_id) AS count
           FROM _adm.system_users su
          WHERE (su.system_group_id = sg.id)) AS qtdusuarios
   FROM _adm.system_group sg
  WHERE (exc_data IS NULL)
  ORDER BY id;


ALTER VIEW _adm.vwgrupolista OWNER TO postgres;

--
-- Name: vwmensagensinternas; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwmensagensinternas AS
 SELECT sm.id,
    sm.system_user_id,
    vw1.nome AS nomeusuariode,
    sm.system_user_to_id,
    vw2.nome AS nomeusuariopara,
    sm.subject,
    sm.message,
    sm.dt_message,
    sm.checked,
    sm.removed,
    sm.viewed,
    sm.attachments,
    sm.inc_data,
    sm.inc_idusuario,
    sm.alt_data,
    sm.alt_idusuario,
    sm.exc_data
   FROM ((_adm.system_message sm
     LEFT JOIN _adm.vwcolaboradorusuario vw1 ON ((vw1.id = sm.system_user_id)))
     LEFT JOIN _adm.vwcolaboradorusuario vw2 ON ((vw2.id = sm.system_user_to_id)));


