--
-- Name: vwpessoacolaborador; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwpessoacolaborador AS
 SELECT t2.id,
    t2.idpessoa,
    t2.tipocolaborador,
    t9.valordominio AS dsctipocolaborador,
    t1.tipopessoa,
        CASE
            WHEN (t1.tipopessoa = 'F'::bpchar) THEN 'Física'::text
            WHEN (t1.tipopessoa = 'J'::bpchar) THEN 'Jurídica'::text
            ELSE 'Outro'::text
        END AS dsctipo,
    t1.cpfcnpj,
    _adm.fn_cpfcnpjformat(t1.cpfcnpj) AS cpfcnpjformat,
    t1.nome,
    t1.nomefantasia,
    t1.sigla,
    (((t1.sigla)::text || ' - '::text) || (t1.nome)::text) AS siglanome,
    t2.genero,
    t5.valordominio AS dscgenero,
    to_char((t2.datanasc)::timestamp with time zone, 'DD/MM/YYYY'::text) AS datanasc,
    t2.estadocivil,
    t6.valordominio AS dscestadocivil,
    t2.numcelular,
        CASE
            WHEN (length(t2.numcelular) = 11) THEN regexp_replace(lpad((t2.numcelular)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numcelular) = 10) THEN regexp_replace(lpad((t2.numcelular)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numcelularformat,
    t2.numtelcom,
        CASE
            WHEN (length(t2.numtelcom) = 11) THEN regexp_replace(lpad((t2.numtelcom)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length(t2.numtelcom) = 10) THEN regexp_replace(lpad((t2.numtelcom)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numtelcomformat,
    t2.numramal,
    t2.iddepartamento,
    t3.nome AS deptonome,
    t2.cargo,
    t2.pthfotocolaborador,
    t2.pthassinaturaemail,
    t2.emailpessoal,
    t2.emailcorporativo,
    t4.id AS idsegmento,
    t4.descricao AS dscsegmento,
    t2.exc_data,
    t2.ativo,
    t2.observacao,
    t7.system_group_id,
    t8.name AS nomegrupo,
    t7.id AS idusuario
   FROM ((((((((_adm.dbpessoa t1
     JOIN _adm.dbcolaborador t2 ON (((t2.idpessoa = t1.id) AND (t2.exc_data IS NULL))))
     LEFT JOIN _adm.dbdepartamento t3 ON ((t3.id = t2.iddepartamento)))
     LEFT JOIN _global.dbsegmentoempresa t4 ON ((t4.id = t1.idsegmento)))
     LEFT JOIN _global.dbcampodominio t5 ON (((t5.grupodominio = 'tg'::bpchar) AND (t5.indicedominio = t2.genero))))
     LEFT JOIN _global.dbcampodominio t6 ON (((t6.grupodominio = 'ec'::bpchar) AND (t6.indicedominio = t2.estadocivil))))
     LEFT JOIN _global.dbcampodominio t9 ON (((t9.grupodominio = 'tc'::bpchar) AND (t9.indicedominio = t2.tipocolaborador))))
     LEFT JOIN _adm.system_users t7 ON ((t7.idcolaborador = t2.id)))
     LEFT JOIN _adm.system_group t8 ON ((t8.id = t2.system_group_id)));


ALTER VIEW _adm.vwpessoacolaborador OWNER TO postgres;

