--
-- Name: vwpessoacolaboradorendereco; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwpessoacolaboradorendereco AS
 SELECT t3.id,
    t2.idpessoa,
    t3.origempessoa,
    'Colaborador'::text AS dscorigempessoa,
    t3.grupoorigem,
    t7.valordominio AS dscgrupoorigem,
    t1.cpfcnpj,
    _adm.fn_cpfcnpjformat(t1.cpfcnpj) AS cpfcnpjformat,
    t1.nome AS nomecolaborador,
    t3.tipoendereco,
    t6.valordominio AS dsctipoendereco,
    t3.dsclogradouro,
    (((t3.dsclogradouro)::text || ', '::text) || (t3.numlogradouro)::text) AS logradouro_num,
    t3.numlogradouro,
    t3.dsccomplemento,
    t3.dscbairro,
    t3.numcep,
    regexp_replace((t3.numcep)::text, '(\d{5})(\d{3})'::text, '\1-\2'::text) AS numcepformat,
    t3.idcidade,
    (((t4.nmecidade)::text || ' - '::text) || (t5.sgluf)::text) AS nomecidade,
    t3.staprincipal,
    t3.ativo,
    t2.observacao,
    t2.inc_data,
    t2.inc_idusuario,
    t2.alt_data,
    t2.alt_idusuario,
    t3.idtipolograd,
    t8.codreflograd,
    t8.dsctipolograd
   FROM (((((((_adm.dbpessoa t1
     JOIN _adm.dbcolaborador t2 ON (((t2.idpessoa = t1.id) AND (t2.exc_data IS NULL))))
     JOIN _adm.dbpessoaendereco t3 ON (((t3.idpessoa = t2.idpessoa) AND (t3.grupoorigem = t2.tipocolaborador))))
     LEFT JOIN _global.dbcidade t4 ON ((t4.id = t3.idcidade)))
     LEFT JOIN _global.dbestado t5 ON ((t5.id = t4.idestado)))
     LEFT JOIN _global.dbcampodominio t6 ON (((t6.grupodominio = 'te'::bpchar) AND (t6.indicedominio = t3.tipoendereco))))
     LEFT JOIN _global.dbcampodominio t7 ON (((t7.grupodominio = 'tc'::bpchar) AND (t7.indicedominio = t3.grupoorigem))))
     LEFT JOIN _global.dbtipologradouro t8 ON ((t8.id = t3.idtipolograd)));


ALTER VIEW _adm.vwpessoacolaboradorendereco OWNER TO postgres;

--
-- Name: vwpessoaempresa; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwpessoaempresa AS
 SELECT t2.id,
    t2.idpessoa,
    t2.tipoempresa,
    t1.tipopessoa,
        CASE
            WHEN (t1.tipopessoa = 'F'::bpchar) THEN 'Física'::text
            WHEN (t1.tipopessoa = 'J'::bpchar) THEN 'Jurídica'::text
            ELSE 'Outro'::text
        END AS dsctipo,
    t1.cpfcnpj,
    _adm.fn_cpfcnpjformat(t1.cpfcnpj) AS cpfcnpjformat,
    t1.nome,
    t1.nomefantasia,
    t1.sigla,
        CASE
            WHEN (t1.sigla IS NULL) THEN (t1.nome)::text
            ELSE (((t1.sigla)::text || ' - '::text) || (t1.nome)::text)
        END AS siglanome,
    t2.numcelular,
        CASE
            WHEN (length((t2.numcelular)::text) = 11) THEN regexp_replace(lpad((t2.numcelular)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length((t2.numcelular)::text) = 10) THEN regexp_replace(lpad((t2.numcelular)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numcelularformat,
    t2.numtelcom,
        CASE
            WHEN (length((t2.numtelcom)::text) = 11) THEN regexp_replace(lpad((t2.numtelcom)::text, 11, '0'::text), '([0-9]{2})([0-9]{5})([0-9]{4})'::text, '(\1) \2-\3'::text)
            WHEN (length((t2.numtelcom)::text) = 10) THEN regexp_replace(lpad((t2.numtelcom)::text, 10, '0'::text), '([0-9]{2})([0-9]{4})([0-9]{4})'::text, '(\1) \2-\3'::text)
            ELSE NULL::text
        END AS numtelcomformat,
    t2.numramal,
    t2.emailemp,
    t2.siteemp,
    t2.pthlogoemp,
    t2.observacao,
    t2.exc_data,
    t2.idiomanativo
   FROM (_adm.dbpessoa t1
     JOIN _adm.dbempresa t2 ON (((t2.idpessoa = t1.id) AND (t2.exc_data IS NULL))));


ALTER VIEW _adm.vwpessoaempresa OWNER TO postgres;

--
-- Name: vwpessoaempresaendereco; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwpessoaempresaendereco AS
 SELECT t3.id,
    t2.idpessoa,
    t3.origempessoa,
    'Empresa'::text AS dscorigempessoa,
    t3.grupoorigem,
    t7.valordominio AS dscgrupoorigem,
    t1.cpfcnpj,
    _adm.fn_cpfcnpjformat(t1.cpfcnpj) AS cpfcnpjformat,
    t1.nome AS nomeempresa,
    t3.tipoendereco,
    t6.valordominio AS dsctipoendereco,
    t3.dsclogradouro,
    (((t3.dsclogradouro)::text || ', '::text) || (t3.numlogradouro)::text) AS logradouro_num,
    t3.numlogradouro,
    t3.dsccomplemento,
    t3.dscbairro,
    t3.numcep,
    regexp_replace((t3.numcep)::text, '(\d{5})(\d{3})'::text, '\1-\2'::text) AS numcepformat,
    t3.idcidade,
    (((t4.nmecidade)::text || ' - '::text) || (t5.sgluf)::text) AS nomecidade,
    t3.staprincipal,
    t3.ativo,
    t2.observacao,
    t2.inc_data,
    t2.inc_idusuario,
    t2.alt_data,
    t2.alt_idusuario,
    t3.idtipolograd,
    t8.codreflograd,
    t8.dsctipolograd
   FROM (((((((_adm.dbpessoa t1
     JOIN _adm.dbempresa t2 ON ((t2.idpessoa = t1.id)))
     JOIN _adm.dbpessoaendereco t3 ON (((t3.idpessoa = t2.idpessoa) AND (t3.grupoorigem = t2.tipoempresa))))
     LEFT JOIN _global.dbcidade t4 ON ((t4.id = t3.idcidade)))
     LEFT JOIN _global.dbestado t5 ON ((t5.id = t4.idestado)))
     JOIN _global.dbcampodominio t6 ON ((((t6.grupodominio)::bpchar = 'te'::bpchar) AND (t6.indicedominio = t3.tipoendereco))))
     JOIN _global.dbcampodominio t7 ON ((((t7.grupodominio)::bpchar = 'eue'::bpchar) AND (t7.indicedominio = t3.grupoorigem))))
     JOIN _global.dbtipologradouro t8 ON ((t8.id = t3.idtipolograd)));


ALTER VIEW _adm.vwpessoaempresaendereco OWNER TO postgres;

--
-- Name: vwusuarioagenda; Type: VIEW; Schema: _adm; Owner: postgres
--

CREATE VIEW _adm.vwusuarioagenda AS
 SELECT d.id,
    d.data_hora_inicial AS data_inicial,
    d.data_hora_final AS data_final,
    d.titulo,
    d.cor,
    d.observacao,
    d.idusuario,
    d.idtipocompromisso,
    t1.valordominio AS desctipocompromisso,
    vwpc.nome AS nomeusuario
   FROM ((_adm.dbusuarioagenda d
     LEFT JOIN _global.dbcampodominio t1 ON (((t1.grupodominio = 'tcom'::bpchar) AND (t1.indicedominio = d.idtipocompromisso))))
     LEFT JOIN _adm.vwpessoacolaborador vwpc ON ((vwpc.idusuario = d.idusuario)))
  ORDER BY vwpc.nome;


