--
-- Name: vwgrupoparcbenef; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwgrupoparcbenef AS
 SELECT dgpb.id,
    dgpb.tipopb,
    t1.valordominio AS desctipopb,
    dgpb.nome,
    dgpb.sigla,
    dgpb.ativo,
    dgpb.inc_data,
    dgpb.inc_idusuario,
    dgpb.alt_data,
    dgpb.alt_idusuario,
    dgpb.exc_data,
    dgpb.exc_idusuario
   FROM (_cadbasicos.dbgrupoparcbenef dgpb
     LEFT JOIN _global.dbcampodominio t1 ON (((t1.grupodominio = 'tpb'::bpchar) AND (t1.indicedominio = dgpb.tipopb))))
  WHERE (dgpb.exc_data IS NULL);


ALTER VIEW _cadbasicos.vwgrupoparcbenef OWNER TO postgres;

--
-- Name: vwbeneficiario; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwbeneficiario AS
 SELECT id AS idbeneficiario,
    tipopb,
    desctipopb,
    ((TRIM(BOTH FROM nome) || ' - '::text) || TRIM(BOTH FROM sigla)) AS nomesigla,
    ((TRIM(BOTH FROM sigla) || ' - '::text) || TRIM(BOTH FROM nome)) AS siglanome,
    sigla,
    nome,
    ativo,
    inc_data,
    inc_idusuario,
    alt_data,
    alt_idusuario,
    exc_data,
    exc_idusuario
   FROM _cadbasicos.vwgrupoparcbenef vwgpb
  WHERE ((tipopb = 1) AND (ativo = 'S'::bpchar))
  ORDER BY nome, sigla;


ALTER VIEW _cadbasicos.vwbeneficiario OWNER TO postgres;

--
-- Name: vwjuiz; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwjuiz AS
 SELECT id,
    nomefantasia,
    nome,
    emailpessoal,
    cargo AS especialista,
    genero,
    dscgenero,
    numcelular,
    numcelularformat,
    ativo,
    dsctipocolaborador,
    id AS idcolaborador,
    id AS idjuiz,
    idpessoa,
    idusuario
   FROM _adm.vwpessoacolaborador vwpc
  WHERE ((tipocolaborador = 4) AND (ativo = 'S'::bpchar));


ALTER VIEW _cadbasicos.vwjuiz OWNER TO postgres;

--
-- Name: vwparceiro; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwparceiro AS
 SELECT id AS idparceiro,
    tipopb,
    desctipopb,
    ((TRIM(BOTH FROM nome) || ' - '::text) || TRIM(BOTH FROM sigla)) AS nomesigla,
    ((TRIM(BOTH FROM sigla) || ' - '::text) || TRIM(BOTH FROM nome)) AS siglanome,
    sigla,
    nome,
    ativo,
    inc_data,
    inc_idusuario,
    alt_data,
    alt_idusuario,
    exc_data,
    exc_idusuario
   FROM _cadbasicos.vwgrupoparcbenef vwgpb
  WHERE ((tipopb = 2) AND (ativo = 'S'::bpchar))
  ORDER BY nome, sigla;


ALTER VIEW _cadbasicos.vwparceiro OWNER TO postgres;

--
-- Name: vwprojetoparcbenef; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwprojetoparcbenef AS
 SELECT vwppb.id,
    vwppb.idprojeto,
    vwppb.tipopb,
    t1.valordominio AS desctipopb,
    vwppb.nome,
    vwppb.nomesigla,
    vwppb.sigla
   FROM (( SELECT dbprjbenef.id,
            dbprjbenef.idprojeto,
            vwbenef.tipopb,
            vwbenef.nome,
            vwbenef.nomesigla,
            vwbenef.sigla,
            vwbenef.ativo
           FROM (_cadbasicos.dbprojetobeneficiario dbprjbenef
             JOIN _cadbasicos.vwbeneficiario vwbenef ON ((dbprjbenef.idbeneficiario = vwbenef.idbeneficiario)))
        UNION
         SELECT dbprjparc.id,
            dbprjparc.idprojeto,
            vwparc.tipopb,
            vwparc.nome,
            vwparc.nomesigla,
            vwparc.sigla,
            vwparc.ativo
           FROM (_cadbasicos.dbprojetoparceiro dbprjparc
             JOIN _cadbasicos.vwparceiro vwparc ON ((dbprjparc.idparceiro = vwparc.idparceiro)))) vwppb
     LEFT JOIN _global.dbcampodominio t1 ON (((t1.grupodominio = 'tpb'::bpchar) AND (t1.indicedominio = vwppb.tipopb))))
  ORDER BY vwppb.nome, vwppb.sigla;


ALTER VIEW _cadbasicos.vwprojetoparcbenef OWNER TO postgres;

--
-- Name: vwprojeto; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwprojeto AS
 SELECT dbprj.id,
    dbprj.sigla,
    dbprj.nome,
    ((TRIM(BOTH FROM dbprj.nome) || ' - '::text) || TRIM(BOTH FROM dbprj.sigla)) AS nomesiglaprojeto,
    ((TRIM(BOTH FROM dbprj.sigla) || ' - '::text) || TRIM(BOTH FROM dbprj.nome)) AS siglanomeprojeto,
    dbprj.instituicao,
    dbprj.descricao,
    dbprj.impactos_esperados,
    dbprj.unid_med_rendimento AS indice_umr,
    dbdomumr.grupodominio AS grpdominio_umr,
    dbdomumr.descdominio AS descdominio_umr,
    dbdomumr.valordominio AS valordominio_umr,
    dbprj.unid_med_adocao AS indice_uma,
    dbdomuma.grupodominio AS grpdominio_uma,
    dbdomuma.descdominio AS descdominio_uma,
    dbdomuma.valordominio AS valordominio_uma,
    dbprj.representacao_valores AS indice_erv,
    dbdomerv.grupodominio AS grpdominio_erv,
    dbdomerv.descdominio AS descdominio_erv,
    dbdomerv.valordominio AS valordominio_erv,
    dbprj.representacao_moeda AS indice_moe,
    dbdommoe.grupodominio AS grpdominio_moe,
    dbdommoe.descdominio AS descdominio_moe,
    dbdommoe.valordominio AS valordominio_moe,
    dbdommoe.aux AS simbolo_moe,
    dbprj.orc_valor_total,
    ((dbdommoe.aux)::text || to_char(dbprj.orc_valor_total, '9G999G990D99'::text)) AS formatvalortotal,
    ((((dbdommoe.aux)::text || ' '::text) || (dbprj.orc_valor_total)::text) || COALESCE(dbdomerv.valordominio, ''::text)) AS valortotalprojeto,
    ((dbprj.probab_exito)::text || '%'::text) AS percprobabexito,
    dbprj.ano_inicio_pesqdesenv,
    dbprj.ano_termino_pesqdesenv,
    dbprj.ano_inicio_adocao,
    dbprj.ano_termino_adocao,
    dbprj.ativo,
    dbprj.inc_data,
    dbprj.inc_idusuario,
    dbprj.alt_data,
    dbprj.alt_idusuario,
    dbprj.exc_data,
    dbprj.exc_idusuario,
    (( SELECT count(vpb.tipopb) AS count
           FROM _cadbasicos.vwprojetoparcbenef vpb
          WHERE ((vpb.idprojeto = dbprj.id) AND (vpb.tipopb = 1))))::text AS qtd_beneficiarios,
    (( SELECT count(vpb.tipopb) AS count
           FROM _cadbasicos.vwprojetoparcbenef vpb
          WHERE ((vpb.idprojeto = dbprj.id) AND (vpb.tipopb = 2))))::text AS qtd_parceiros
   FROM ((((_cadbasicos.dbprojeto dbprj
     LEFT JOIN _global.dbcampodominio dbdommoe ON (((dbdommoe.grupodominio = 'moe'::bpchar) AND (dbdommoe.indicedominio = dbprj.representacao_moeda))))
     LEFT JOIN _global.dbcampodominio dbdomumr ON (((dbdomumr.grupodominio = 'umr'::bpchar) AND (dbdomumr.indicedominio = dbprj.unid_med_rendimento))))
     LEFT JOIN _global.dbcampodominio dbdomuma ON (((dbdomuma.grupodominio = 'uma'::bpchar) AND (dbdomuma.indicedominio = dbprj.unid_med_adocao))))
     LEFT JOIN _global.dbcampodominio dbdomerv ON (((dbdomerv.grupodominio = 'erv'::bpchar) AND (dbdomerv.indicedominio = dbprj.representacao_valores))))
  WHERE (dbprj.exc_data IS NULL);


ALTER VIEW _cadbasicos.vwprojeto OWNER TO postgres;

--
-- Name: vwprojetobeneficiario; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwprojetobeneficiario AS
 SELECT dbprjbenef.id,
    dbprjbenef.idprojeto,
    vwprj.nomesiglaprojeto,
    vwprj.sigla AS siglaprojeto,
    vwprj.nome AS nomeprojeto,
    vwbenef.idbeneficiario,
    vwbenef.tipopb,
    vwbenef.nome AS nomebeneficiario,
    vwbenef.nomesigla AS nomesiglabeneficiario,
    vwbenef.sigla AS siglabeneficiario,
    dbprjbenef.percparticipacao
   FROM ((_cadbasicos.dbprojetobeneficiario dbprjbenef
     JOIN _cadbasicos.vwprojeto vwprj ON ((dbprjbenef.idprojeto = vwprj.id)))
     JOIN _cadbasicos.vwbeneficiario vwbenef ON ((dbprjbenef.idbeneficiario = vwbenef.idbeneficiario)))
  ORDER BY vwbenef.sigla, vwbenef.nome;


ALTER VIEW _cadbasicos.vwprojetobeneficiario OWNER TO postgres;

--
-- Name: vwprojetoparceiro; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwprojetoparceiro AS
 SELECT dbprjparc.id,
    dbprjparc.idprojeto,
    vwprj.nomesiglaprojeto,
    vwprj.sigla AS siglaprojeto,
    vwprj.nome AS nomeprojeto,
    vwparc.idparceiro,
    vwparc.tipopb,
    vwparc.nome AS nomeparceiro,
    vwparc.nomesigla AS nomesiglaparceiro,
    vwparc.sigla AS siglaparceiro
   FROM ((_cadbasicos.dbprojetoparceiro dbprjparc
     JOIN _cadbasicos.vwprojeto vwprj ON ((dbprjparc.idprojeto = vwprj.id)))
     JOIN _cadbasicos.vwparceiro vwparc ON ((dbprjparc.idparceiro = vwparc.idparceiro)))
  ORDER BY vwparc.sigla, vwparc.nome;


ALTER VIEW _cadbasicos.vwprojetoparceiro OWNER TO postgres;

--
-- Name: vwrodada; Type: VIEW; Schema: _cadbasicos; Owner: postgres
--

CREATE VIEW _cadbasicos.vwrodada AS
 SELECT dbrdd.id,
    dbrdd.nome,
    dbrdd.sigla,
    ((TRIM(BOTH FROM dbrdd.nome) || ' - '::text) || TRIM(BOTH FROM dbrdd.sigla)) AS nomesiglarodada,
    dbrdd.dataprevistainicio,
    dbrdd.dataprevistafim,
    to_char((dbrdd.dataprevistainicio)::timestamp with time zone, 'DD/MM/YYYY'::text) AS formatdataprevistainicio,
    to_char((dbrdd.dataprevistafim)::timestamp with time zone, 'DD/MM/YYYY'::text) AS formatdataprevistafim,
    dbrdd.idgestoroperacao,
    dbrdd.dataultimaconfig,
    dbrdd.flgemoperacao,
    dbrdd.indsituacao AS indicesituacao,
    dbdomstrdd.grupodominio AS grpsituacao,
    dbdomstrdd.descdominio AS descsituacao,
    dbdomstrdd.valordominio AS valorsituacao,
    dbdomstrdd.aux AS simbolosituacao,
    dbrdd.ativo,
    dbrdd.corgestao,
    dbrdd.inc_data,
    dbrdd.inc_idusuario,
    dbrdd.alt_data,
    dbrdd.alt_idusuario,
    dbrdd.exc_data,
    dbrdd.exc_idusuario
   FROM (_cadbasicos.dbrodada dbrdd
     LEFT JOIN _global.dbcampodominio dbdomstrdd ON (((dbdomstrdd.grupodominio = 'strd'::bpchar) AND (dbdomstrdd.indicedominio = dbrdd.indsituacao))))
  WHERE (dbrdd.exc_data IS NULL);


ALTER VIEW _cadbasicos.vwrodada OWNER TO postgres;

