--
-- Name: vwcidades; Type: VIEW; Schema: _global; Owner: postgres
--

CREATE VIEW _global.vwcidades AS
 SELECT dbc.id,
    TRIM(BOTH FROM dbc.nmecidade) AS nmecidade,
    ((TRIM(BOTH FROM dbc.nmecidade) || ' - '::text) || (dbe.sgluf)::text) AS nmecidadeuf,
    dbc.idestado,
    dbe.nmeestado,
    dbe.sgluf,
    dbc.codibge,
    dbc.numcordlatlon,
    dbc.nmecidadeupper
   FROM (_global.dbcidade dbc
     LEFT JOIN _global.dbestado dbe ON ((dbe.id = dbc.idestado)));


ALTER VIEW _global.vwcidades OWNER TO postgres;

--
-- Name: vwcomponentes; Type: VIEW; Schema: _global; Owner: postgres
--

CREATE VIEW _global.vwcomponentes AS
 SELECT id,
    identificacao,
    descricao,
    idcontexto,
        CASE
            WHEN (idcontexto = 1) THEN 'Form'::text
            WHEN (idcontexto = 2) THEN 'Grid'::text
            WHEN (idcontexto = 3) THEN 'Abas'::text
            ELSE 'Outros'::text
        END AS dsccontexto,
    ativo,
    inc_data,
    inc_idusuario,
    alt_data,
    alt_idusuario,
    exc_data,
    auxiliar
   FROM _global.dbcomponentes t1
  WHERE (ativo = 'S'::bpchar)
  ORDER BY id;


ALTER VIEW _global.vwcomponentes OWNER TO postgres;

--
-- Name: vwfuncionalidadecampolocaliza; Type: VIEW; Schema: _global; Owner: postgres
--

CREATE VIEW _global.vwfuncionalidadecampolocaliza AS
 SELECT t1.id,
    t1.idfunc,
    t1.campo,
    t1.dsccampo,
    t1.grupocomparacao,
    t1.tipocampo,
    t1.grupodominio,
    t1.cporetcombo,
    t1.cporetgrid,
    t2.descdominio AS comparadordesc,
    t2.valordominio AS comparadorvalor
   FROM ((_global.dbfuncionalidadecampolocaliza t1
     LEFT JOIN _global.dbcampodominio t2 ON ((t2.grupodominio = t1.grupocomparacao)))
     LEFT JOIN _global.dbcampodominio t3 ON ((t2.grupodominio = t1.grupodominio)));


ALTER VIEW _global.vwfuncionalidadecampolocaliza OWNER TO postgres;

