--
-- Name: vw_hierarq_referencia; Type: VIEW; Schema: _referencia; Owner: postgres
--

CREATE VIEW _referencia.vw_hierarq_referencia AS
 WITH dimaspecto_cte AS (
         SELECT DISTINCT da.idmetodologia,
            da.id AS iddimaspecto,
                CASE
                    WHEN (da.idmetodologia = 1) THEN ((('Dimensão: '::text || rtrim(SUBSTRING(upper(public.unaccent((da.nome)::text)) FROM 1 FOR (POSITION(('-'::text) IN (upper(public.unaccent((da.nome)::text)))) - 1)))) || ' | Aspecto: '::text) || rtrim(SUBSTRING(upper(public.unaccent((da.nome)::text)) FROM (POSITION(('-'::text) IN (upper(public.unaccent((da.nome)::text)))) + 1) FOR length(upper(public.unaccent((da.nome)::text))))))
                    WHEN (da.idmetodologia = 2) THEN ('Dimensão: INSTITUCIONAL | Aspecto: '::text || upper(public.unaccent((da.nome)::text)))
                    ELSE upper(public.unaccent((da.nome)::text))
                END AS hierarquia,
            da.sigla AS ch,
            da.nivel
           FROM _referencia.dbreferencia da
          WHERE (da.nivel = 1)
        ), criterio_cte AS (
         SELECT DISTINCT c.idmetodologia,
            c.id_autoref AS iddimaspecto,
            c.id AS idcriterio,
            c.valorimportancia,
            ('Criterio: '::text || (c.nome)::text) AS hierarquia,
            c.sigla AS ch,
            c.nivel
           FROM _referencia.dbreferencia c
          WHERE (c.nivel = 2)
          ORDER BY c.id_autoref
        ), indicador_cte AS (
         SELECT DISTINCT i.idmetodologia,
            i.id_autoref AS idcriterio,
            i.id AS idindicador,
            i.valorimportancia,
            ('Indicador: '::text || (i.nome)::text) AS hierarquia,
            i.sigla AS ch,
            i.nivel
           FROM _referencia.dbreferencia i
          WHERE (i.nivel = 3)
          ORDER BY i.id_autoref
        )
 SELECT COALESCE(iddimaspecto, idcriterio, idindicador) AS id,
    idmetodologia,
    ch,
    hierarquia,
    valorimportancia,
    iddimaspecto,
    idcriterio,
    idindicador,
    nivel
   FROM ( SELECT d.idmetodologia,
            d.ch,
            d.hierarquia,
            NULL::numeric(4,3) AS valorimportancia,
            d.iddimaspecto,
            NULL::integer AS idcriterio,
            NULL::integer AS idindicador,
            d.nivel
           FROM dimaspecto_cte d
        UNION ALL
         SELECT c.idmetodologia,
            c.ch,
            c.hierarquia,
            c.valorimportancia,
            NULL::integer AS iddimaspecto,
            c.idcriterio,
            NULL::integer AS idindicador,
            c.nivel
           FROM criterio_cte c
        UNION ALL
         SELECT i.idmetodologia,
            i.ch,
            i.hierarquia,
            i.valorimportancia,
            NULL::integer AS iddimaspecto,
            NULL::integer AS idcriterio,
            i.idindicador,
            i.nivel
           FROM indicador_cte i) arvore
  ORDER BY idmetodologia, ch;


ALTER VIEW _referencia.vw_hierarq_referencia OWNER TO postgres;

--
-- Name: vw_treeview_referencia; Type: VIEW; Schema: _referencia; Owner: postgres
--

CREATE VIEW _referencia.vw_treeview_referencia AS
 SELECT idmetodologia,
    ch,
    (
        CASE
            WHEN (nivel = 1) THEN ''::text
            WHEN (nivel = 2) THEN ('|'::text || repeat('_'::text, (('-1'::integer + nivel) * 3)))
            ELSE ((repeat(' '::text, (('-1'::integer + nivel) * 3)) || '|'::text) || repeat('_'::text, (('-2'::integer + nivel) * 3)))
        END || hierarquia) AS hierarquia,
    valorimportancia,
    nivel
   FROM _referencia.vw_hierarq_referencia;


ALTER VIEW _referencia.vw_treeview_referencia OWNER TO postgres;

--
-- Name: vwmetodologia; Type: VIEW; Schema: _referencia; Owner: postgres
--

CREATE VIEW _referencia.vwmetodologia AS
 SELECT id,
    nome,
    sigla,
    (((sigla)::text || ' - '::text) || (nome)::text) AS siglanomemetodologia,
    ativo
   FROM _referencia.dbmetodologia dm
  WHERE (ativo = 'S'::bpchar);


ALTER VIEW _referencia.vwmetodologia OWNER TO postgres;

