-- Name: vwprojetosativos; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwprojetosativos AS
 SELECT id,
    sigla,
    nome,
    nomesiglaprojeto,
    siglanomeprojeto,
    instituicao,
    descricao,
    impactos_esperados,
    indice_umr,
    grpdominio_umr,
    descdominio_umr,
    valordominio_umr,
    indice_uma,
    grpdominio_uma,
    descdominio_uma,
    valordominio_uma,
    indice_erv,
    grpdominio_erv,
    descdominio_erv,
    valordominio_erv,
    indice_moe,
    grpdominio_moe,
    descdominio_moe,
    valordominio_moe,
    simbolo_moe,
    orc_valor_total,
    formatvalortotal,
    valortotalprojeto,
    percprobabexito,
    ano_inicio_pesqdesenv,
    ano_termino_pesqdesenv,
    ano_inicio_adocao,
    ano_termino_adocao,
    ativo,
    inc_data,
    inc_idusuario,
    alt_data,
    alt_idusuario,
    exc_data,
    exc_idusuario
   FROM _cadbasicos.vwprojeto vp
  WHERE (ativo = 'S'::bpchar);


ALTER VIEW _rodadaconfig.vwprojetosativos OWNER TO postgres;

--
-- Name: vwrodadacriterios; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwrodadacriterios AS
 SELECT dbrc.id,
    dbrc.idrodada,
    vrod.nome AS nomerodada,
    vrod.nomesiglarodada,
    dbrc.idmetodologia,
    dbrm.nome AS nomemetodologia,
    dbrm.sigla AS siglametodologia,
    vcref.id AS idreferencia,
    vcref.ch,
    vcref.hierarquia,
    vcref.valorimportancia,
    vcref.iddimaspecto,
    vcref.idcriterio,
    vcref.idindicador,
    vcref.nivel
   FROM (((_rodadaconfig.dbrodadacriterios dbrc
     JOIN _referencia.dbmetodologia dbrm ON ((dbrc.idmetodologia = dbrm.id)))
     JOIN _cadbasicos.vwrodada vrod ON ((dbrc.idrodada = vrod.id)))
     JOIN _referencia.vw_hierarq_referencia vcref ON ((dbrc.idreferencia = vcref.id)))
  ORDER BY vcref.ch;


ALTER VIEW _rodadaconfig.vwrodadacriterios OWNER TO postgres;

--
-- Name: VIEW vwrodadacriterios; Type: COMMENT; Schema: _rodadaconfig; Owner: postgres
--

COMMENT ON VIEW _rodadaconfig.vwrodadacriterios IS 'View que descreve a tabela de relacionamento da Rodada x Criterio-de-Ref Configurado';


--
-- Name: vwrodadafases; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwrodadafases AS
 SELECT dbrf.id,
    dbdomstrdd.valordominio AS valortipofase,
    dbrf.idrodada,
    d.nome AS nomerodada,
    d.sigla AS siglarodada,
    ((TRIM(BOTH FROM d.nome) || ' - '::text) || TRIM(BOTH FROM d.sigla)) AS nomesiglarodada,
    dbrf.idfase,
    f.nome AS nomefase,
    f.corgestao,
    f.ordem,
    dbrf.dataprevistainicio,
    dbrf.dataprevistafim,
    to_char((dbrf.dataprevistainicio)::timestamp with time zone, 'DD/MM/YYYY'::text) AS formatdataprevistainicio,
    to_char((dbrf.dataprevistafim)::timestamp with time zone, 'DD/MM/YYYY'::text) AS formatdataprevistafim,
    dbrf.qtddias,
    dbrf.flgconcluida,
        CASE
            WHEN ((((dbrf.dataprevistafim)::date - (now())::date) + 1) <= dbrf.qtddias) THEN (((((dbrf.dataprevistafim)::date - (now())::date) + 1))::numeric / (dbrf.qtddias)::numeric)
            ELSE (0)::numeric
        END AS percandamento,
    (((dbrf.dataprevistafim)::date - (now())::date) + 1) AS qtddiaspassados
   FROM (((_rodadaconfig.dbrodadafase dbrf
     LEFT JOIN _cadbasicos.dbrodada d ON ((d.id = dbrf.idrodada)))
     LEFT JOIN _global.dbfase f ON ((f.id = dbrf.idfase)))
     LEFT JOIN _global.dbcampodominio dbdomstrdd ON (((dbdomstrdd.grupodominio = 'tfs'::bpchar) AND (dbdomstrdd.indicedominio = f.indtipofase))))
  ORDER BY dbrf.idrodada, dbrf.idfase, f.ordem;


ALTER VIEW _rodadaconfig.vwrodadafases OWNER TO postgres;

--
-- Name: vwrodadajuizes; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwrodadajuizes AS
 SELECT dbrj.id,
    dbrj.idrodada,
    vr.nome AS nomerodada,
    vr.nomesiglarodada,
    dbrj.idjuiz,
    vj.nome AS nomejuiz,
    vj.nomefantasia,
    (((vj.nome)::text || ' - '::text) || (vj.nomefantasia)::text) AS nomeapelidojuiz,
    dbrj.flgconfirmado
   FROM ((_rodadaconfig.dbrodadajuizes dbrj
     JOIN _cadbasicos.vwrodada vr ON ((vr.id = dbrj.idrodada)))
     JOIN _cadbasicos.vwjuiz vj ON ((vj.id = dbrj.idjuiz)))
  ORDER BY vj.nome;


ALTER VIEW _rodadaconfig.vwrodadajuizes OWNER TO postgres;

--
-- Name: vwrodadametodologias; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwrodadametodologias AS
 SELECT dbrm.id,
    dbrm.idrodada,
    vr.nome AS nomerodada,
    vr.sigla AS siglarodada,
    vr.nomesiglarodada,
    dbrm.idmetodologia,
    dbm.nome,
    dbm.sigla,
    dbm.ativo
   FROM ((_rodadaconfig.dbrodadametodologias dbrm
     JOIN _cadbasicos.vwrodada vr ON ((dbrm.idrodada = vr.id)))
     JOIN _referencia.dbmetodologia dbm ON ((dbrm.idmetodologia = dbm.id)))
  ORDER BY dbm.nome;


ALTER VIEW _rodadaconfig.vwrodadametodologias OWNER TO postgres;

--
