COMMENT ON VIEW _rodadaconfig.vwrodadametodologias IS 'View que descreve a tabela de relacionamento da Rodada x Metodologias do Escores';


--
-- Name: vwrodadaprojetos; Type: VIEW; Schema: _rodadaconfig; Owner: postgres
--

CREATE VIEW _rodadaconfig.vwrodadaprojetos AS
 SELECT dbrp.id,
    dbrp.idrodada,
    vr.nome AS nomerodada,
    vr.nomesiglarodada,
    dbrp.idprojeto,
    vp.nome AS nomeprojeto,
    vp.nomesiglaprojeto
   FROM ((_rodadaconfig.dbrodadaprojetos dbrp
     JOIN _cadbasicos.vwrodada vr ON ((vr.id = dbrp.idrodada)))
     JOIN _cadbasicos.vwprojeto vp ON ((vp.id = dbrp.idprojeto)))
  ORDER BY vp.nomesiglaprojeto;


ALTER VIEW _rodadaconfig.vwrodadaprojetos OWNER TO postgres;

